"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

from dataclasses import dataclass
import re


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += "-" + ".".join(self.prerelease)
        if self.build:
            result += "+" + ".".join(self.build)
        return result


_IDENTIFIER = re.compile(r"^[0-9A-Za-z-]+$")
_CORE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(.*)$")


def _identifiers(value: str, *, prerelease: bool) -> tuple[str, ...]:
    parts = value.split(".")
    if not parts or any(not _IDENTIFIER.fullmatch(part) for part in parts):
        raise ValueError("invalid version identifier")
    if prerelease and any(part.isdigit() and len(part) > 1 and part[0] == "0" for part in parts):
        raise ValueError("numeric prerelease identifiers must not have leading zeros")
    return tuple(parts)


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError("version must be a string")
    match = _CORE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid semantic version: {text!r}")
    major, minor, patch = (int(match.group(i)) for i in (1, 2, 3))
    tail = match.group(4)
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()
    if tail.startswith("-"):
        content = tail[1:]
        # Build metadata, if present, follows the prerelease.
        before_build, sep, build_text = content.partition("+")
        prerelease = _identifiers(before_build, prerelease=True)
        if sep:
            build = _identifiers(build_text, prerelease=False)
    elif tail.startswith("+"):
        build = _identifiers(tail[1:], prerelease=False)
    elif tail:
        raise ValueError(f"invalid semantic version: {text!r}")
    return Version(major, minor, patch, prerelease, build)


def _version(value: str | Version) -> Version:
    return value if isinstance(value, Version) else parse(value)


def _compare(a: Version, b: Version) -> int:
    core_a = (a.major, a.minor, a.patch)
    core_b = (b.major, b.minor, b.patch)
    if core_a != core_b:
        return (core_a > core_b) - (core_a < core_b)
    if not a.prerelease or not b.prerelease:
        return (not a.prerelease) - (not b.prerelease)
    for left, right in zip(a.prerelease, b.prerelease):
        if left == right:
            continue
        left_num, right_num = left.isdigit(), right.isdigit()
        if left_num and right_num:
            return (int(left) > int(right)) - (int(left) < int(right))
        if left_num != right_num:
            return -1 if left_num else 1
        return (left > right) - (left < right)
    return (len(a.prerelease) > len(b.prerelease)) - (len(a.prerelease) < len(b.prerelease))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare(_version(a), _version(b))


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _version(version)
    if not isinstance(range_, str) or not range_.strip():
        raise ValueError("range must not be empty")

    def parse_comparator(token: str) -> list[tuple[str, Version]]:
        if token.startswith("^") or token.startswith("~"):
            kind, raw = token[0], token[1:]
            base = parse(raw)
            if kind == "~":
                upper = Version(base.major, base.minor + 1, 0)
            elif base.major:
                upper = Version(base.major + 1, 0, 0)
            elif base.minor:
                upper = Version(0, base.minor + 1, 0)
            else:
                upper = Version(0, 0, base.patch + 1)
            return [(">=", base), ("<", upper)]
        op = "="
        raw = token
        for candidate_op in (">=", "<=", ">", "<", "="):
            if token.startswith(candidate_op):
                op, raw = candidate_op, token[len(candidate_op):]
                break
        if not raw:
            raise ValueError(f"invalid comparator: {token!r}")
        return [(op, parse(raw))]

    sets = range_.split("||")
    if any(not item.strip() for item in sets):
        raise ValueError("invalid empty comparator set")
    for item in sets:
        tokens = item.split()
        # Operators must be attached to a complete version.
        comparators = [comp for token in tokens for comp in parse_comparator(token)]
        if candidate.prerelease and not any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) ==
            (candidate.major, candidate.minor, candidate.patch)
            for _, bound in comparators
        ):
            continue
        def matches(op: str, bound: Version) -> bool:
            order = compare(candidate, bound)
            return {
                "=": order == 0,
                ">": order > 0,
                ">=": order >= 0,
                "<": order < 0,
                "<=": order <= 0,
            }[op]

        if all(matches(op, bound) for op, bound in comparators):
            return True
    return False

