"""ISO 8601 durations.

A duration is ``P`` followed by date parts ``nY``, ``nM``, ``nW``, ``nD``
(in that order, each optional), then optionally ``T`` followed by time parts
``nH``, ``nM``, ``nS`` (in that order, each optional). Each ``n`` is a
non-negative integer, except that seconds may have a decimal fraction
(``PT1.5S``). At least one part must be present, and ``T`` must be followed
by at least one time part, so ``P``, ``PT``, ``P1H``, ``1D``, ``PT1.5M`` and
``P1D2Y`` are invalid. Parsing is case-sensitive; invalid input raises
``ValueError``.

``format`` writes the canonical form: parts in the order above, parts that
are zero left out, ``T`` only when a time part is present, and seconds
without a fraction when they are whole (``PT1S``, ``PT1.5S``). The zero
duration is ``PT0S``.

``add`` adds a duration to a datetime: first years and months, keeping the
day of the month but clamping it to the last day of the resulting month
(Jan 31 plus one month is Feb 28, or 29 in a leap year), then weeks, days,
hours, minutes, and seconds as exact elapsed time.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation
import calendar
import math
import re


@dataclass(frozen=True)
class Duration:
    years: int = 0
    months: int = 0
    weeks: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: float = 0


def parse(text: str) -> Duration:
    """Parse an ISO 8601 duration."""
    if not isinstance(text, str) or not text.startswith("P"):
        raise ValueError("duration must start with 'P'")
    if text.count("T") > 1:
        raise ValueError("duration contains more than one 'T'")
    if "T" in text:
        date_text, time_text = text[1:].split("T")
        if not time_text:
            raise ValueError("'T' must be followed by a time part")
    else:
        date_text, time_text = text[1:], None

    values = {"Y": 0, "M": 0, "W": 0, "D": 0, "H": 0, "m": 0, "S": 0}

    def parse_section(section: str, units: str) -> None:
        pos = 0
        previous = -1
        order = {unit: i for i, unit in enumerate(units)}
        while pos < len(section):
            match = re.match(r"(\d+(?:\.\d+)?)([A-Za-z])", section[pos:])
            if not match:
                raise ValueError(f"invalid duration component at {section[pos:]!r}")
            number, unit = match.groups()
            if unit not in order or order[unit] <= previous:
                raise ValueError(f"invalid or out-of-order duration unit: {unit!r}")
            if "." in number and unit != "S":
                raise ValueError("only seconds may have a fractional value")
            previous = order[unit]
            key = "m" if units == "HMS" and unit == "M" else unit
            try:
                parsed = Decimal(number)
            except InvalidOperation as exc:
                raise ValueError("invalid duration number") from exc
            if unit != "S":
                values[key] = int(parsed)
            else:
                values[key] = float(parsed)
                if not math.isfinite(values[key]):
                    raise ValueError("seconds are too large")
            pos += match.end()

    parse_section(date_text, "YMWD")
    if time_text is not None:
        parse_section(time_text, "HMS")
    if not date_text and not time_text:
        raise ValueError("duration must contain at least one part")
    return Duration(values["Y"], values["M"], values["W"], values["D"],
                    values["H"], values["m"], values["S"])


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    if not isinstance(duration, Duration):
        raise ValueError("expected a Duration")
    integer_fields = (duration.years, duration.months, duration.weeks,
                      duration.days, duration.hours, duration.minutes)
    if any(type(value) is not int or value < 0 for value in integer_fields):
        raise ValueError("duration fields must be non-negative integers")
    try:
        seconds = Decimal(str(duration.seconds))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("seconds must be a non-negative number") from exc
    if not seconds.is_finite() or seconds < 0:
        raise ValueError("seconds must be a non-negative finite number")
    date_parts = "".join(f"{value}{unit}" for value, unit in (
        (duration.years, "Y"), (duration.months, "M"),
        (duration.weeks, "W"), (duration.days, "D")) if value)
    time_parts = "".join(f"{value}{unit}" for value, unit in (
        (duration.hours, "H"), (duration.minutes, "M")) if value)
    if seconds:
        second_text = seconds.__format__("f")
        if "." in second_text:
            second_text = second_text.rstrip("0").rstrip(".")
        time_parts += second_text + "S"
    if not date_parts and not time_parts:
        return "PT0S"
    return "P" + date_parts + ("T" + time_parts if time_parts else "")


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    # Normalize years and months together before applying elapsed units.
    month_index = moment.year * 12 + (moment.month - 1) + duration.years * 12 + duration.months
    year, month0 = divmod(month_index, 12)
    month = month0 + 1
    day = min(moment.day, calendar.monthrange(year, month)[1])
    result = moment.replace(year=year, month=month, day=day)
    return result + timedelta(weeks=duration.weeks, days=duration.days,
                             hours=duration.hours, minutes=duration.minutes,
                             seconds=duration.seconds)
"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

from datetime import datetime, time, timedelta
import re


_MONTHS = {name: i for i, name in enumerate(
    ("JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"), 1
)}
_WEEKDAYS = {name: i for i, name in enumerate(("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"))}


def _field(text: str, low: int, high: int, names: dict[str, int] | None = None,
           sunday: bool = False) -> set[int]:
    """Parse one cron field into its normalized set of values."""
    result: set[int] = set()

    def value(raw: str) -> int:
        key = raw.upper()
        if names and key in names:
            return names[key]
        if not re.fullmatch(r"\d+", raw):
            raise ValueError(f"invalid cron value: {raw!r}")
        number = int(raw)
        if not low <= number <= high:
            raise ValueError(f"cron value out of range: {raw!r}")
        return number

    for item in text.split(","):
        if not item:
            raise ValueError("empty cron list item")
        if item.count("/") > 1:
            raise ValueError(f"invalid cron item: {item!r}")
        if "/" in item:
            base, step_text = item.split("/")
            if not re.fullmatch(r"\d+", step_text) or int(step_text) == 0:
                raise ValueError(f"invalid cron step: {step_text!r}")
            step = int(step_text)
        else:
            base, step = item, 1

        if base == "*":
            start, stop = low, high
        elif base.count("-") == 1:
            first, last = base.split("-")
            start, stop = value(first), value(last)
            if start > stop:
                raise ValueError(f"reversed cron range: {base!r}")
        else:
            start = stop = value(base)
            # A stepped single value runs from that value through the end.
            if "/" in item:
                stop = high
        values = range(start, stop + 1, step)
        result.update(0 if sunday and number == 7 else number for number in values)
    return result


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    if not isinstance(after, datetime) or after.tzinfo is not None:
        raise ValueError("after must be a naive datetime")
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")
    minutes = _field(fields[0], 0, 59)
    hours = _field(fields[1], 0, 23)
    dom = _field(fields[2], 1, 31)
    months = _field(fields[3], 1, 12, _MONTHS)
    dow = _field(fields[4], 0, 7, _WEEKDAYS, sunday=True)
    dom_star, dow_star = fields[2] == "*", fields[4] == "*"

    # Calendar arithmetic gives a clear five-year search horizon, including
    # leap days, while handling Feb 29 as Feb 28 at the horizon if needed.
    try:
        end = after.replace(year=after.year + 5)
    except ValueError:
        end = after.replace(year=after.year + 5, day=28)
    first_day = after.date()
    final_day = end.date()
    current = first_day
    while current <= final_day:
        if current.month in months:
            month_day_match = current.day in dom
            weekday_match = ((current.weekday() + 1) % 7) in dow
            if dom_star and dow_star:
                day_match = True
            elif dom_star:
                day_match = weekday_match
            elif dow_star:
                day_match = month_day_match
            else:
                day_match = month_day_match or weekday_match
            if day_match:
                for hour in sorted(hours):
                    for minute in sorted(minutes):
                        candidate = datetime.combine(current, time(hour, minute))
                        if after < candidate <= end:
                            return candidate
        current += timedelta(days=1)
    raise ValueError("cron expression has no run within five years")

